//! Reads VIA definition files through the public API, against the hand-written
//! `fixtures/synthetic/via-definition-second-model.json`. Expected values are worked out by
//! hand from that file, not generated by the loader.

#[cfg(test)]
mod tests {
    use std::path::PathBuf;

    use openkeychron_via::{
        DefinitionError, DefinitionKey, DeviceRegistry, Rectangle, RegistryError, ViaDefinition,
        WriteAccess,
    };

    fn second_model_text() -> String {
        std::fs::read_to_string(
            PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                .join("../../fixtures/synthetic/via-definition-second-model.json"),
        )
        .unwrap()
    }

    fn second_model() -> ViaDefinition {
        ViaDefinition::from_json(&second_model_text()).unwrap()
    }

    fn rectangle(x: f32, y: f32, width: f32, height: f32) -> Rectangle {
        Rectangle {
            x,
            y,
            width,
            height,
        }
    }

    /// A definition with a 2 × 2 matrix whose single keymap row is `row`.
    fn with_keymap_row(row: &str) -> String {
        format!(
            r#"{{"name": "Test", "vendorId": "0x3434", "productId": "0x0001",
                "matrix": {{"rows": 2, "cols": 2}}, "layouts": {{"keymap": [{row}]}}}}"#
        )
    }

    #[test]
    fn reads_the_identity_and_matrix_size() {
        let definition = second_model();
        assert_eq!(definition.name, "Synthetic second model");
        assert_eq!(
            (definition.vendor_id, definition.product_id),
            (0x3434, 0x0950)
        );
        assert_eq!((definition.rows, definition.columns), (2, 4));
    }

    #[test]
    fn lists_keys_in_file_order_with_their_matrix_positions() {
        let matrices: Vec<_> = second_model().keys.iter().map(|key| key.matrix).collect();
        assert_eq!(
            matrices,
            [[0, 0], [0, 1], [0, 2], [0, 3], [1, 0], [1, 1], [1, 3]]
        );
    }

    #[test]
    fn accumulates_x_offsets_and_widths_along_a_row() {
        let definition = second_model();
        let bounds: Vec<_> = definition.keys[..4].iter().map(|key| key.bounds).collect();
        assert_eq!(
            bounds,
            [
                rectangle(0.0, 0.0, 1.0, 1.0),
                rectangle(1.5, 0.0, 1.0, 1.0),
                rectangle(2.5, 0.0, 1.0, 1.0),
                rectangle(3.75, 0.0, 1.0, 1.0),
            ]
        );
    }

    #[test]
    fn starts_each_row_at_x_zero_one_unit_lower_plus_its_y_offset() {
        let definition = second_model();
        assert_eq!(
            definition.key(1, 0).unwrap().bounds,
            rectangle(0.0, 1.25, 1.5, 1.0)
        );
    }

    #[test]
    fn resets_width_and_height_after_each_key() {
        let definition = second_model();
        assert_eq!(
            definition.key(1, 3).unwrap().bounds,
            rectangle(3.0, 1.25, 1.0, 2.0)
        );
    }

    #[test]
    fn places_a_secondary_rectangle_in_absolute_coordinates() {
        assert_eq!(
            second_model().key(1, 1),
            Some(&DefinitionKey {
                matrix: [1, 1],
                bounds: rectangle(1.75, 1.25, 1.25, 2.0),
                secondary_bounds: Some(rectangle(1.5, 1.25, 1.5, 1.0)),
                encoder: None,
            })
        );
    }

    #[test]
    fn gives_plain_keys_no_secondary_rectangle() {
        assert_eq!(second_model().key(1, 3).unwrap().secondary_bounds, None);
    }

    #[test]
    fn reads_the_encoder_index_from_the_tenth_label() {
        let encoders: Vec<_> = second_model()
            .keys
            .iter()
            .filter_map(|key| key.encoder.map(|encoder| (key.matrix, encoder)))
            .collect();
        assert_eq!(encoders, [([0, 3], 0)]);
    }

    #[test]
    fn moves_the_layout_so_its_top_left_key_starts_at_the_origin() {
        let definition = ViaDefinition::from_json(&with_keymap_row(
            r#"[{"x": 0.5, "y": 0.25, "x2": -0.25, "w2": 1.5}, "0,0", "0,1"]"#,
        ))
        .unwrap();
        assert_eq!(definition.keys[0].bounds, rectangle(0.25, 0.0, 1.0, 1.0));
        assert_eq!(
            definition.keys[0].secondary_bounds,
            Some(rectangle(0.0, 0.0, 1.5, 1.0))
        );
        assert_eq!(definition.keys[1].bounds, rectangle(1.25, 0.0, 1.0, 1.0));
    }

    #[test]
    fn has_no_key_at_unused_or_out_of_range_positions() {
        let definition = second_model();
        assert_eq!(definition.key(1, 2), None);
        assert_eq!(definition.key(2, 0), None);
        assert_eq!(definition.key(0, 4), None);
    }

    #[test]
    fn rejects_text_that_is_not_json() {
        let error = ViaDefinition::from_json("not json").unwrap_err();
        assert!(
            matches!(&error, DefinitionError::Json { message } if message.contains("line 1")),
            "{error:?}"
        );
    }

    #[test]
    fn rejects_ids_that_are_not_hex_strings() {
        let text = second_model_text().replace(r#""0x0950""#, r#""2384""#);
        assert_eq!(
            ViaDefinition::from_json(&text),
            Err(DefinitionError::InvalidId {
                field: "productId",
                value: "2384".to_owned(),
            })
        );
    }

    #[test]
    fn rejects_an_id_with_a_sign() {
        let text = second_model_text().replace(r#""0x0950""#, r#""0x+950""#);
        assert_eq!(
            ViaDefinition::from_json(&text),
            Err(DefinitionError::InvalidId {
                field: "productId",
                value: "0x+950".to_owned(),
            })
        );
    }

    #[test]
    fn accepts_an_empty_list_of_layout_options() {
        let text = second_model_text().replace(r#""layouts": {"#, r#""layouts": { "labels": [],"#);
        assert_eq!(ViaDefinition::from_json(&text), Ok(second_model()));
    }

    #[test]
    fn rejects_an_empty_matrix() {
        let text = second_model_text().replace(r#""rows": 2"#, r#""rows": 0"#);
        assert_eq!(
            ViaDefinition::from_json(&text),
            Err(DefinitionError::EmptyMatrix)
        );
    }

    #[test]
    fn rejects_layout_options() {
        let text = second_model_text().replace(
            r#""layouts": {"#,
            r#""layouts": { "labels": ["Split Backspace"],"#,
        );
        assert_eq!(
            ViaDefinition::from_json(&text),
            Err(DefinitionError::LayoutOptions)
        );
    }

    #[test]
    fn rejects_a_key_that_belongs_to_a_layout_option() {
        assert_eq!(
            ViaDefinition::from_json(&with_keymap_row(r#"["0,0\n\n\n0,1"]"#)),
            Err(DefinitionError::LayoutOptions)
        );
    }

    #[test]
    fn rejects_properties_that_would_change_geometry_it_cannot_represent() {
        for property in ["r", "rx", "ry", "a", "d"] {
            assert_eq!(
                ViaDefinition::from_json(&with_keymap_row(&format!(
                    r#"["0,0", {{"{property}": 1}}, "0,1"]"#
                ))),
                Err(DefinitionError::UnsupportedProperty {
                    keymap_row: 0,
                    item: 1,
                    property: property.to_owned(),
                }),
                "{property}"
            );
        }
    }

    #[test]
    fn rejects_a_geometry_property_that_is_not_a_number() {
        assert_eq!(
            ViaDefinition::from_json(&with_keymap_row(r#"[{"w": "2"}, "0,0"]"#)),
            Err(DefinitionError::InvalidProperty {
                keymap_row: 0,
                item: 0,
                property: "w".to_owned(),
            })
        );
    }

    #[test]
    fn rejects_an_item_that_is_neither_a_label_nor_properties() {
        assert_eq!(
            ViaDefinition::from_json(&with_keymap_row(r#"["0,0", 7]"#)),
            Err(DefinitionError::UnexpectedItem {
                keymap_row: 0,
                item: 1,
            })
        );
    }

    #[test]
    fn rejects_a_label_that_is_not_a_matrix_position() {
        for label in ["", "0", "a,b", "0,0,0", "300,0"] {
            assert_eq!(
                ViaDefinition::from_json(&with_keymap_row(&format!(r#"["{label}"]"#))),
                Err(DefinitionError::InvalidMatrixLabel {
                    keymap_row: 0,
                    item: 0,
                    label: label.to_owned(),
                }),
                "{label}"
            );
        }
    }

    #[test]
    fn rejects_a_matrix_position_outside_the_matrix() {
        assert_eq!(
            ViaDefinition::from_json(&with_keymap_row(r#"["0,0", "1,2"]"#)),
            Err(DefinitionError::MatrixOutOfRange {
                matrix: [1, 2],
                rows: 2,
                columns: 2,
            })
        );
    }

    #[test]
    fn rejects_two_keys_on_one_matrix_position() {
        assert_eq!(
            ViaDefinition::from_json(&with_keymap_row(r#"["0,1", "0, 1"]"#)),
            Err(DefinitionError::DuplicateKey { matrix: [0, 1] })
        );
    }

    #[test]
    fn rejects_an_encoder_label_without_an_index() {
        assert_eq!(
            ViaDefinition::from_json(&with_keymap_row(r#"["0,0\n\n\n\n\n\n\n\n\nknob"]"#)),
            Err(DefinitionError::InvalidEncoder {
                keymap_row: 0,
                item: 0,
                label: "knob".to_owned(),
            })
        );
    }

    #[test]
    fn built_in_registry_knows_the_v5_max_iso_with_french_legends() {
        let registry = DeviceRegistry::built_in();
        let layout = registry.layout(0x3434, 0x0951).unwrap();
        assert_eq!((layout.rows(), layout.columns()), (6, 19));
        assert_eq!(layout.legend(2, 1), Some("A"));
        assert!(!layout.has_key(0, 1));
    }

    #[test]
    fn built_in_registry_knows_no_other_model() {
        assert!(DeviceRegistry::built_in().layout(0x3434, 0x0950).is_none());
    }

    #[test]
    fn registry_finds_a_registered_definition_by_its_vendor_and_product_id() {
        let mut registry = DeviceRegistry::built_in();
        registry.register(second_model()).unwrap();
        let layout = registry.layout(0x3434, 0x0950).unwrap();
        assert_eq!((layout.rows(), layout.columns()), (2, 4));
        assert!(layout.has_key(1, 1));
        assert!(!layout.has_key(1, 2));
        assert_eq!(layout.legend(1, 1), None);
    }

    #[test]
    fn registry_refuses_a_second_layout_for_the_same_device() {
        let text = second_model_text().replace(r#""0x0950""#, r#""0x0951""#);
        let mut registry = DeviceRegistry::built_in();
        assert_eq!(
            registry.register(ViaDefinition::from_json(&text).unwrap()),
            Err(RegistryError::AlreadyRegistered {
                vendor_id: 0x3434,
                product_id: 0x0951,
            })
        );
        assert_eq!(
            registry.layout(0x3434, 0x0951).unwrap().legend(2, 1),
            Some("A")
        );
    }

    #[test]
    fn built_in_v5_max_iso_is_verified_for_writes_over_a_cable() {
        let registry = DeviceRegistry::built_in();
        let model = registry.model(0x3434, 0x0951).unwrap();
        assert_eq!(
            (model.name(), model.write_access()),
            ("V5 Max ISO", WriteAccess::VerifiedOverCable)
        );
    }

    #[test]
    fn a_registered_definition_is_read_only() {
        let mut registry = DeviceRegistry::built_in();
        registry.register(second_model()).unwrap();
        let model = registry.model(0x3434, 0x0950).unwrap();
        assert_eq!(
            (model.name(), model.write_access()),
            ("Synthetic second model", WriteAccess::ReadOnly)
        );
    }

    #[test]
    fn write_verified_models_leave_out_a_registered_definition() {
        let mut registry = DeviceRegistry::built_in();
        registry.register(second_model()).unwrap();
        let writable: Vec<_> = registry
            .write_verified_models()
            .map(|(id, model)| (id, model.name()))
            .collect();
        assert_eq!(writable, [((0x3434, 0x0951), "V5 Max ISO")]);
    }
}
